		withKey(retryInput("2026-10-02T03:30:00Z", "2026-10-02T03:31:00Z",
			"succeeded", nil), "retry-2"))
	if secondReplay.Body.String() != second.Body.String() {
		t.Fatalf("late second replay = %s", secondReplay.Body.String())
	}
	if got := f.request(http.MethodGet, "/api/v1/jobs/"+jobID+"/runs/"+runID, nil); len(decodeBody(t, got)["results"].([]any)) != 3 {
		t.Fatalf("unexpected attempt count: %s", got.Body.String())
	}
}

