	final := f.request(http.MethodPost, url2,
		withKey(retryInput("2026-10-02T03:30:00Z", "2026-10-02T03:31:00Z",
			"succeeded", nil), "retry-2"))
	if final.Code != http.StatusCreated || len(decodeBody(t, final)["results"].([]any)) != 3 {
