	if err != nil {
		return nil, err
	}
	defer tx.Rollback()

	var storedFingerprint string
	var storedCount int
	err = tx.QueryRow(
		`SELECT request_fingerprint, result_attempt_count FROM retry_idempotency_keys
		  WHERE job_id = ? AND run_id = ? AND idempotency_key = ?`,
		jobID, runID, key,
	).Scan(&storedFingerprint, &storedCount)
